void ManageUsers(){if(!Can("admin"))return;D response=b.Call("users");var staff=J.Rows(response,"users").Where(u=>J.Text(u,"role")!="admin").ToList();if(staff.Count==0){MessageBox.Show("배포 사용자 계정을 먼저 추가하세요.");return;}var catalog=J.Rows(b.Call("permissionCatalog"),"items");using(var f=new Form{Text="배포 사용자 권한 · 기본은 모두 차단",Width=750,Height=720}){Style.Form(f);var frame=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),RowCount=5,ColumnCount=1};frame.RowStyles.Add(new RowStyle(SizeType.Absolute,42));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,40));frame.RowStyles.Add(new RowStyle(SizeType.Percent,100));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,65));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,50));var users=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};foreach(D u in staff)users.Items.Add(new Choice(J.Text(u,"id"),J.Text(u,"name")+" / "+J.Text(u,"username")));var enabled=new CheckBox{Text="이 계정의 로그인 허용",Dock=DockStyle.Fill};var checks=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,BorderStyle=BorderStyle.FixedSingle,IntegralHeight=false};foreach(D r in catalog)checks.Items.Add(J.Text(r,"label"));users.SelectedIndexChanged+=(o,e)=>{D u=staff[users.SelectedIndex];enabled.Checked=J.Bool(u,"enabled");var values=u.ContainsKey("permissions")?((System.Collections.IEnumerable)u["permissions"]).Cast<object>().Select(Convert.ToString).ToArray():new string[0];for(int i=0;i<catalog.Count;i++)checks.SetItemChecked(i,values.Contains(J.Text(catalog[i],"key")));};frame.Controls.Add(users,0,0);frame.Controls.Add(enabled,0,1);frame.Controls.Add(checks,0,2);frame.Controls.Add(new Label{Text="편집을 허용하면 해당 조회도 함께 허용됩니다.\n저장 즉시 해당 사용자의 기존 로그인이 해제되므로 다시 로그인해야 합니다. 금액 포함 항목은 권한 이름을 확인하세요.",Dock=DockStyle.Fill,ForeColor=Style.Muted},0,3);frame.Controls.Add(Style.Button("권한 저장",(o,e)=>{try{var permissions=checks.CheckedIndices.Cast<int>().Select(i=>J.Text(catalog[i],"key")).ToArray();b.Call("updateUser",J.Row("id",J.Text