void OpenCheck(D original){D row=original==null?J.Row("id",Guid.NewGuid().ToString(),"name","현장 실측·시공 점검","items",J.Rows(b.Call("checklistTemplate"),"items").ToArray()):J.Clone(original);using(var f=new Form{Text="현장 점검표 · 확인 기록이며 안전 승인서가 아닙니다",Width=1000,Height=760}){Style.Form(f);var frame=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),RowCount=4,ColumnCount=1};frame.RowStyles.Add(new RowStyle(SizeType.Absolute,90));frame.RowStyles.Add(new RowStyle(SizeType.Percent,100));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,75));frame.RowStyles.Add(new RowStyle(SizeType.Absolute,50));var top=new FlowLayoutPanel{Dock=DockStyle.Fill};var name=new TextBox{Width=350,Text=J.Text(row,"name")};var project=new ComboBox{Width=420,DropDownStyle=ComboBoxStyle.DropDownList};project.Items.Add(new Choice("","현장 선택"));foreach(D r in J.Rows(state,"projects"))project.Items.Add(new Choice(J.Text(r,"id"),J.Text(r,"name")));project.SelectedIndex=0;for(int i=0;i<project.Items.Count;i++)if(((Choice)project.Items[i]).Id==J.Text(row,"project"))project.SelectedIndex=i;top.Controls.Add(name);top.Controls.Add(project);top.Controls.Add(new Label{Text="실측·골조·매립 설비·목공·LED·전기·인계 항목을 현장에서 확인하고 메모하세요. 체크는 구조·법규 승인이나 합격 판정이 아닙니다.",Width=900,Height=45});var g=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};g.Columns.Add(new DataGridViewCheckBoxColumn{Name="done",HeaderText="확인",FillWeight=15});g.Columns.Add("label","점검 항목");g.Columns.Add("note","실측값 · 결과 · 보수 메모");g.Columns[1].ReadOnly=true;foreach(D item in J.Rows(row,"items")){int i=g.Rows.Add(J.Bool(item,"done"),J.Text(item,"label"),J.Text(item,"note"));g.Rows[i].Tag=item;}var memo=new TextBox{Dock=DockStyle.Fill,Multiline=true,Text=J.Text(row,"note"),ScrollBars=ScrollBars.Vertical};frame.Controls.Add(top,0,0);frame.Controls.Add(g,0,1);frame.Controls.Add(memo,0,2);var save=Style.Button("점검표 저장",(o,e)=>{g.EndEdit();if(project.SelectedIndex==0){MessageBox.Show("연결 현장을 선택하세요.");return;}row["name"]=name.Text.Trim();row["project"]=((Choice)project.SelectedItem).Id;row["note"]=memo.Text;row["updatedAt"]=DateTime.Now.ToString("o");var items=new List<D>();foreach(DataGridViewRow gr in g.Rows){D item=J.Clone((D)gr.Tag);item["done"]=Convert.ToBoolean(gr.Cells[0].Value);item["note"]=Convert.ToString(gr.Cells[2].Value);items.Add(item);}row["items"]=items.ToArray();if(Store("siteChecks",row))f.Close();});save.Enabled=Can("siteChecks.write");g.ReadOnly=!Can("siteChecks.write");frame.Controls.Add(save,0,3);f.Controls.Add(frame);f.ShowDialog(this);}}
